/* The invoice font, embedded.
 *
 * WHY A FONT IS SHIPPED AT ALL. jsPDF's built-in faces are the PDF standard 14,
 * which are WinAnsi-encoded and DO NOT CONTAIN THE RUPEE SIGN. Drawing \u20b9 with
 * Helvetica gives a blank box, on every line of an Indian invoice. So a real
 * font has to be embedded, and that is the whole reason this file exists.
 *
 * Inter, SIL Open Font License 1.1 (rsms.me/inter), subset to Latin plus
 * \u20b9 \u2013 \u2014 \u00b7 \u2022 and the quote marks, with hinting and the layout tables dropped
 * because a PDF uses none of them. 412 KB became 9.8 KB each; both faces
 * together cost 26 KB of this bundle.
 *
 * Regenerate with fontTools if the character set ever needs more:
 *   subset.Options(layout_features=[], hinting=False, desubroutinize=True)
 */
window.ZS_INVOICE_FONTS = {
  regular: '',
  semibold: ''
};
